/**
 * tests/fixtures/e2e-vault-clean is generated by scripts/make-e2e-vault-clean.ts (D-56, E2E T3):
 * two projects, every Workspace blank, 23 notes. These checks keep the generator's output the
 * vault the first-use E2E starts from.
 */
import { existsSync } from 'node:fs';
import { mkdtemp, readdir, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { createVault, parseMarkdown, type Vault } from '@/lib/vault';
import { vaultIntegrity } from '../../scripts/demo-snapshot-relink';
import { buildE2eVaultClean, LIBRARY_FILES } from '../../scripts/make-e2e-vault-clean';

const ROOT = process.cwd();
const FIXTURE = path.join(ROOT, 'tests/fixtures/e2e-vault-clean');
const S3 = path.join(ROOT, 'demo-vault/.snapshots/S3-D48');
const P1 = '20_项目/个人AI战略';
const P2 = '20_项目/渠道与服务';
const LIBRARY = '10_资料库';
const METHOD_LIBRARY = '00_团队知识/方法库';
const GITKEEPS = [
  `${P1}/WS-A 买方/review/.gitkeep`,
  `${P1}/WS-A 买方/调查/.gitkeep`,
  `${P1}/WS-B 用户/review/.gitkeep`,
  `${P1}/WS-B 用户/调查/.gitkeep`,
  `${P1}/假设/.gitkeep`,
  `${P1}/决策/.gitkeep`,
  `${P2}/WS-C 中型客户/review/.gitkeep`,
  `${P2}/WS-C 中型客户/调查/.gitkeep`,
  `${P2}/假设/.gitkeep`,
  `${P2}/决策/.gitkeep`,
];

let root: string;
let vault: Vault;

async function walk(dir: string, base = dir): Promise<string[]> {
  const out: string[] = [];
  for (const d of await readdir(dir, { withFileTypes: true })) {
    const full = path.join(dir, d.name);
    if (d.isDirectory()) out.push(...(await walk(full, base)));
    else out.push(path.relative(base, full).split(path.sep).join('/'));
  }
  return out.sort();
}

/** The raw text before the closing `---` (empty when the file has no frontmatter). */
function frontmatterOf(text: string): string {
  const { body } = parseMarkdown(text);
  return text.slice(0, text.length - body.length);
}

beforeAll(async () => {
  root = await mkdtemp(path.join(tmpdir(), 'e2e-vault-clean-'));
  await buildE2eVaultClean(root);
  vault = createVault(root);
});

afterAll(async () => {
  await rm(root, { recursive: true, force: true });
});

describe('e2e-vault-clean', () => {
  it('has the 23 notes and the 10 .gitkeep files, under exactly two projects', async () => {
    const files = await walk(root);
    expect(files.filter((f) => f.endsWith('.md'))).toHaveLength(23);
    expect(files.filter((f) => f.endsWith('.gitkeep'))).toEqual(GITKEEPS);

    const projects = (await vault.list('20_项目')).map((e) => e.name);
    expect(projects).toHaveLength(2);
    expect(new Set(projects)).toEqual(new Set(['个人AI战略', '渠道与服务']));
  });

  it('is a fully linked, valid vault (ambiguous bare [[项目]] counts as broken)', async () => {
    expect(await vaultIntegrity(vault)).toEqual([]);
  });

  it('has no bare [[项目]] left in any frontmatter', async () => {
    const notes = (await walk(root)).filter((f) => f.endsWith('.md'));
    const offenders: string[] = [];
    for (const f of notes) {
      if (frontmatterOf(await readFile(path.join(root, f), 'utf8')).includes('[[项目]]')) offenders.push(f);
    }
    expect(offenders).toEqual([]);
  });

  it('starts every workspace at 拆题中 and has no reports, plans, workplans, hypotheses, decisions or reviews', async () => {
    const notes = await Promise.all((await walk(root)).filter((f) => f.endsWith('.md')).map((f) => vault.read(f)));
    const workspaces = notes.filter((n) => n.path.endsWith('/workspace.md'));
    expect(workspaces.map((n) => n.path)).toHaveLength(3);
    for (const ws of workspaces) expect(ws.data.stage, ws.path).toBe('拆题中');

    const forbidden = new Set(['report', 'research_plan', 'workplan', 'hypothesis', 'decision', 'review']);
    expect(notes.filter((n) => forbidden.has(String(n.data.type))).map((n) => n.path)).toEqual([]);

    for (const dir of [`${P1}/假设`, `${P1}/决策`, `${P2}/假设`, `${P2}/决策`]) {
      expect(await readdir(path.join(root, dir))).toEqual(['.gitkeep']);
    }
  });

  it('copies the 5 library notes byte for byte from S3-D48', async () => {
    expect((await readdir(path.join(root, LIBRARY))).sort()).toEqual([...LIBRARY_FILES].sort());
    for (const name of LIBRARY_FILES) {
      const [built, source] = await Promise.all([
        readFile(path.join(root, LIBRARY, name), 'utf8'),
        readFile(path.join(S3, LIBRARY, name), 'utf8'),
      ]);
      expect(parseMarkdown(built).body, name).toBe(parseMarkdown(source).body);
    }
  });

  it('copies the method library bodies byte for byte from S3-D48', async () => {
    const names = await readdir(path.join(S3, METHOD_LIBRARY));
    expect(names).toHaveLength(5);
    for (const name of names) {
      const [built, source] = await Promise.all([
        readFile(path.join(root, METHOD_LIBRARY, name), 'utf8'),
        readFile(path.join(S3, METHOD_LIBRARY, name), 'utf8'),
      ]);
      expect(parseMarkdown(built).body, name).toBe(parseMarkdown(source).body);
    }
  });

  it('gives WS-A and WS-B the descriptions the E2E asks for', async () => {
    const [wsA, wsB] = await Promise.all([
      readFile(path.join(root, `${P1}/WS-A 买方/workspace.md`), 'utf8'),
      readFile(path.join(root, `${P1}/WS-B 用户/workspace.md`), 'utf8'),
    ]);
    expect(wsA).toContain('买方采购逻辑：企业买单的首要条件。');
    expect(wsA).not.toContain('IT 和 CIO 为什么买、预算从哪来。');
    expect(wsB).toContain('员工实际在用什么 AI。');
    expect(wsB).not.toContain('员工这一侧的使用价值和采用障碍。');
  });

  it('marks the simulated meeting and the simulated policy as 模拟', async () => {
    for (const p of [`${P1}/会议/2026-10-16 高层周会（模拟）.md`, '00_团队知识/高层方针/2026财年商用PC业务方针（模拟）.md']) {
      const n = await vault.read(p);
      expect(n.data.simulated, p).toBe(true);
      expect(n.data.publisher, p).toBe('模拟');
    }
  });

  it('gives the three workspaces their owners', async () => {
    const owners = await Promise.all(
      [`${P1}/WS-A 买方`, `${P1}/WS-B 用户`, `${P2}/WS-C 中型客户`].map(async (p) => (await vault.read(`${p}/workspace.md`)).data.owner),
    );
    expect(owners).toEqual(['Junior A', 'Junior B', 'Junior B']);
  });

  it.skipIf(!existsSync(FIXTURE))('matches the committed fixture byte for byte', async () => {
    const committed = await walk(FIXTURE);
    const built = await walk(root);
    expect(committed).toEqual(built);
    for (const f of built) {
      expect(await readFile(path.join(FIXTURE, f)), f).toEqual(await readFile(path.join(root, f)));
    }
  });
});
